// Selected official RuleBtn; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

[RequireComponent(typeof(Button))]
public class RuleBtn : MonoBehaviour
{
	protected Button mClickBtn;
	private System.Action<string, bool> popup;
	public void Configure(System.Action<string, bool> value) { popup = value; }

	[SerializeField]
	protected string mRuleKey;

	[SerializeField]
	protected bool mIsDynamicHeightRulePanel;

	private void Awake()
	{


		mClickBtn = ((Component)this).GetComponent<Button>();
		((UnityEvent)mClickBtn.onClick).AddListener((UnityAction)OnClickBtn);
	}

	public void SetRuleKey(string ruleKey)
	{
		mRuleKey = ruleKey;
	}

	private void OnDestroy()
	{


		((UnityEvent)mClickBtn.onClick).RemoveListener((UnityAction)OnClickBtn);
	}
	private void OnClickBtn()
	{ (popup ?? throw new System.InvalidOperationException("Original rule window is unbound."))(mRuleKey, mIsDynamicHeightRulePanel); }

}
}
